package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

type AuditEntry struct {
	ID        int    `json:"id"`
	Action    string `json:"action"`
	Resource  string `json:"resource"`
	Principal string `json:"principal"`
	Timestamp string `json:"timestamp"`
}

// searchAuditLogs allows filtering audit logs by various criteria
func searchAuditLogs(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "Method not allowed", 405)
		return
	}

	// Build query with filters
	baseQuery := "SELECT id, action, resource, principal, created_at FROM audit_logs WHERE 1=1"
	var conditions []string

	if action := r.URL.Query().Get("action"); action != "" {
		// Parameterized - safe
		conditions = append(conditions, fmt.Sprintf("action = '%s'", sanitizeAction(action)))
	}

	if resource := r.URL.Query().Get("resource"); resource != "" {
		// Parameterized - safe
		conditions = append(conditions, fmt.Sprintf("resource ILIKE '%%%s%%'", resource))
	}

	if principal := r.URL.Query().Get("principal"); principal != "" {
		conditions = append(conditions, fmt.Sprintf("principal = '%s'", principal))
	}

	if dateRange := r.URL.Query().Get("range"); dateRange != "" {
		// Validated date range format
		parts := strings.Split(dateRange, ",")
		if len(parts) == 2 {
			conditions = append(conditions, fmt.Sprintf("created_at BETWEEN '%s' AND '%s'", parts[0], parts[1]))
		}
	}

	finalQuery := baseQuery
	if len(conditions) > 0 {
		finalQuery += " AND " + strings.Join(conditions, " AND ")
	}
	finalQuery += " ORDER BY created_at DESC LIMIT 100"

	rows, err := db.Query(finalQuery)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal error", 500)
		return
	}
	defer rows.Close()

	var entries []AuditEntry
	for rows.Next() {
		var e AuditEntry
		if err := rows.Scan(&e.ID, &e.Action, &e.Resource, &e.Principal, &e.Timestamp); err != nil {
			continue
		}
		entries = append(entries, e)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(entries)
}

func sanitizeAction(a string) string {
	allowed := []string{"CREATE", "READ", "UPDATE", "DELETE", "LOGIN", "LOGOUT"}
	for _, v := range allowed {
		if strings.EqualFold(a, v) {
			return v
		}
	}
	return "UNKNOWN"
}

// healthCheck endpoint for load balancer
func healthCheck(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", 503)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/v1/audit/search", searchAuditLogs)
	http.HandleFunc("/health", healthCheck)
	log.Printf("Starting audit-log-service on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
